/* mode 4: diagnostics. D(k) = $0038_0300 + 4k:
 *  0-6  read-back of FILL, SRC, DST, SIZE, XSIZE, YSIZE, STRIDE after writing known values
 *  7    STATUS after the fill into the gap (expect 6), 8 (unused)
 *  then per simple test t (k = 9 + 4t): STATUS, wrong bytes, first wrong offset, (got << 8) | expected */
#define D(k)    (g1t_d[(k)])
static void simple(u32 t, u32 ctrl, u32 fill, u32 src, u32 dst, u32 n, u32 ps, u32 mir)
{
	volatile u8 *m = (volatile u8 *)0;
	u32 i, bad = 0, st;
	u8 e;
	for (i = 0; i < n + 32; i++) m[dst - 16 + i] = 0xEE;
	setregs(fill, src, dst, n, 0, 0, 0, 0);
	st = start_and_wait(ctrl);
	D(9 + 4 * t) = st;
	for (i = 0; i < n + 32; i++) {
		u32 a = dst - 16 + i, p = a - dst;
		if (a < dst || a >= dst + n) e = 0xEE;
		else if (ctrl & 4) e = ps == 1 ? (u8)fill : ps == 2 ? ((a & 1) ? (u8)fill : (u8)(fill >> 8)) : (u8)(fill >> (8 * (3 - (a & 3))));
		else e = m[src + (mir ? (n / ps - 1 - p / ps) * ps + p % ps : p)];
		if (m[a] != e) { if (!bad) { D(11 + 4 * t) = i; D(12 + 4 * t) = (m[a] << 8) | e; } bad++; }
	}
	D(10 + 4 * t) = bad;
}
static void diag(void)
{
	u32 i, st;
	for (i = 0; i < 60; i++) D(i) = 0;
	setregs(0x11223344, 0x02345678, 0x0389ABCD, 0x00012345, 0x0000ABCD, 0x00001234, 0x5678, 0x9ABC);
	for (i = 0; i < 7; i++) D(i) = G(4 + 4 * i);
	setregs(0x11223344, 0, 0x00C00000, 64, 0, 0, 0, 0);
	st = start_and_wait(0x14);
	D(7) = st;
	simple(0, 0x00, 0, SRCA, DSTA, 64, 1, 0);                  /* SDRAM aligned copy */
	simple(1, 0x14, 0xA1B2C3D4UL, 0, DSTA + 0x1000, 64, 4, 0);  /* SDRAM 32-bit fill */
	simple(2, 0x00, 0, SRCA + 1, SRAMA + 0x100003, 100, 1, 0);  /* SDRAM -> SRAM, odd */
	simple(3, 0x00, 0, SRAMA + 0x5, DSTA + 0x3000, 100, 1, 0);  /* SRAM -> SDRAM, odd */
	simple(4, 0x00, 0, SRCA + 2, VRAMA + 0x180001, 100, 1, 0);  /* SDRAM -> VRAM A */
	simple(5, 0x00, 0, VRAMA + 0x3, DSTA + 0x5001, 100, 1, 0);  /* VRAM A -> SDRAM */
	simple(6, 0x48, 0, VRAMB + 0x100, VRAMB + 0x100000, 32, 2, 1);	/* VRAM B -> VRAM B 16-bit mirror */
	simple(7, 0x0C, 0x1234, 0, SRAMA + 0x100001, 33, 2, 0);    /* SRAM 16-bit fill, odd */
	simple(8, 0x00, 0, SRAMA + 0x10, SRAMA + 0x100011, 1200, 1, 0);	/* SRAM -> SRAM, 3 chunks */
}

static void speed(u32 mode)
{
	switch (mode) {
	case 1:  setregs(0, SRCA, DSTA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 2:  setregs(0xA5A5A5A5UL, 0, DSTA, 0x100000, 0, 0, 0, 0); start_and_wait(0x14); break;
	case 3:  setregs(0, SRCA + 1, DSTA + 3, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 5:  setregs(0, SRCA, SRAMA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 6:  setregs(0, SRAMA, DSTA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 7:  setregs(0, SRAMA, SRAMA + 0x100000, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 8:  setregs(0, SRCA, VRAMA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 9:  setregs(0, VRAMA, DSTA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 10: setregs(0, VRAMB, VRAMB + 0x100000, 0x100000, 0, 0, 0, 0); start_and_wait(0x00); break;
	case 11: setregs(0x5A5A5A5AUL, 0, SRAMA, 0x100000, 0, 0, 0, 0); start_and_wait(0x14); break;
	case 12: setregs(0x5A5A5A5AUL, 0, VRAMA, 0x100000, 0, 0, 0, 0); start_and_wait(0x14); break;
	default: setregs(0, SRAMA, DSTA, 0x100000, 0, 0, 0, 0); start_and_wait(0x00FF0000UL); break;	/* 13: tenure 255 */
	}
}

int g1t_gdma_main(void)
{
	u32 mode = R(0x00), n = 0, i;
	volatile u32 *s = (volatile u32 *)SRCA;
	for (i = 0x04; i < 0x94; i += 4) R(i) = 0;
	for (i = 0; i < 0x100000; i++) s[i] = (i * 0x9E3779B1UL) ^ (i >> 7);   /* 4 MB of source pattern (SDRAM) */
	if (mode == 0 || mode == 4) {											/* patterns in the other banks' areas */
		volatile u32 *p = (volatile u32 *)SRAMA;
		for (i = 0; i < 0x80000; i++) p[i] = (i * 0x61C88647UL) ^ 0x55AA0000UL;
		p = (volatile u32 *)VRAMA;
		for (i = 0; i < 0xC0000; i++) p[i] = (i * 0x2545F491UL) ^ 0x0F0F0000UL;
		p = (volatile u32 *)VRAMB;
		for (i = 0; i < 0x80000; i++) p[i] = (i * 0x9E3779B9UL) ^ 0xC3C30000UL;
	}
	if (mode == 4) { diag(); R(0x08) = 0x600DF00DUL; return 0; }
	directed();
	R(0x08) = 0x600DF00DUL;
	while (timers_jiffies() < g1t_end) {
		if (mode == 0) check_one(n); else speed(mode);
		n++;
		R(0x04) = n;
		R(0x50) = *(volatile u32 *)0xFEC8010CUL;	/* GUI late lines (channel B GUI mode), for gdmarun */
	}
	return 0;
}
